class Poisson {
	constructor (x, y, w, h, d) {
		let nx = floor(w/d);
		let ny = floor(h/d);
		let searchDS = new SearchDS (x-d, y-d, w+d*2, h+d*2, nx, ny);
		let ncells = nx*ny;
		let cells = [];
		for (let i = 0; i < ncells; i++) {
			cells.push (i,i,i,i,i,i,i,i)
		}
		shuffle(cells,true);
		let points = []
		for (let i of cells) {
			let p = createVector(x + i % nx * d+ random(d),
													 y + int(i / nx) * d + random(d));
			let mbr = MBR.fromRect(p.x-d,p.y-d,d*2,d*2);
			let ok = true;
			for (let q of searchDS.valuesInMbr(mbr)) {
				if (q.dist(p) < d) {
					ok = false;
					break;
				}
			}
			if (ok) {
				p.index = points.length;
				points.push (p);
				searchDS.add(MBR.fromRect(p.x, p.y, 1, 1), p)
			}
		}
		Object.assign(this, {x, y, w, h, d, searchDS, points})
	}
	get length() {
		return this.points.length;
	}
	pop () {
		return this.points.pop();
	}
}

