let freePos, cnter, last, d, rings, trails;
let searchDS, candPoints, finished;
let palette, bkg, icolor;
const batchSize = 10;

function setup() {
	createCanvas(windowWidth, windowHeight);
	generate();
}

function mousePressed() {
	generate();
}

function generate() {
	palette = random(palettes);
	bkg = palette[0];
	palette = palette.slice(1);
	d = max(width, height) / 40;
	candPoints = new Poisson(0, 0, width, height, d);
	cnter = candPoints.pop();
	freePos = [];
	trails = [
		[cnter]
	]
	last = {
		p: cnter,
		center: cnter,
		ring: 0,
		ang: 0,
		free: false
	};
	rings = 0;
	searchDS = new SearchDS(-d, -d, width + d*2, height + d*2);
	addToDS(last);
	finished = false;
}

function addToDS(obj) {
	let mbr = MBR.fromRect(obj.p.x - d, obj.p.y - d, d * 2, d * 2);
	if (obj.free) {
		obj.index = freePos.length;
		freePos.push(obj);
	}
	searchDS.add(mbr, obj);
}

function* freeNeighbors(p, dmax = d) {
	let mbr = MBR.fromRect(p.x - dmax, p.y - dmax, dmax * 2, dmax * 2);
	if (mbr.containedIn(searchDS.mbr))
		for (let obj of searchDS.valuesInMbr(mbr)) {
			if (obj.free) yield obj;
		}
}

function* neighborsWithin(p, dmax) {
	let mbr = MBR.fromRect(p.x - dmax, p.y - dmax, dmax * 2, dmax * 2);
	for (let obj of searchDS.valuesInMbr(mbr)) {
		if (obj.p.dist(p) <= dmax) yield obj;
	}
}

function addRing() {
	rings++;

	let r = d * rings;
	let perimeter = TAU * r;
	let n = floor(perimeter / d);
	let dAng = TAU / n;
	let ang = random(TAU);
	let v = createVector(r, 0);
	//print ({r,d,perimeter,ang,dAng,n,v})
	for (let i = 0; i < n; i++) {
		let p = cnter.copy().add(v.copy().rotate(ang));
		// freePos.push ({p, 
		// 							 center: cnter, ring:rings, ang});
		if (searchDS.mbr.contains(p, d / 2) &&
			neighborsWithin(p, d - 0.1).next().done) {
			addToDS({
				p,
				center: cnter,
				ring: rings,
				ang,
				free: true
			});
		}
		ang += dAng;
	}
}

function draw() {
	background(bkg);
	noFill();
	strokeJoin(ROUND);
	strokeWeight(d / 2);
	let icolor = 0;
	for (let trail of trails) {
		stroke(palette[icolor]);
		icolor = (icolor + 1) % palette.length;
		beginShape()
		for (let p of trail) {
			vertex(p.x, p.y)
		}
		endShape();
	}
	for (let ibatch = 0; ibatch < batchSize; ibatch++) {
		if (finished) return;

		let placed = false;
		let tries = 0;
		let bestDist = Infinity,
			best = -1;
		let lastPos = last.p;
		while (!placed && tries++ < 2) {
			if (freePos.length == 0) {
				if (random() < 0.4) {
					do {
						if (candPoints.length == 0) {
							finished = true;
							return;
						}
						cnter = candPoints.pop();
					} while (!neighborsWithin(cnter, d - 0.1).next().done);
					rings = 0;
				}
				addRing();
				addRing();
			}
			for (let neigh of freeNeighbors(lastPos, d * 2)) {
				//let {p,ang,ring} = freePos[i];
				let p = neigh.p;
				let dlast = p.dist(lastPos);
				if (dlast < bestDist) {
					best = neigh;
					bestDist = dlast;
					placed = true;
				}
			}
		}
		if (!placed) {
			if (freePos.length == 0) return;
			best = freePos.pop();
			bestDist = best.p.dist(lastPos);
		} else {
			let k = freePos.length - 1;
			freePos[best.index] = freePos[k];
			freePos[best.index].index = best.index;
			freePos.pop();
		}
		let prev = last;
		last = best;
		last.free = false;
		if (bestDist < d * 1.42) {
			if (prev.ring != last.ring ||
				prev.center != last.center) trails[trails.length - 1].push(last.p);
			else {
				let ang0 = (prev.ang + TAU) % TAU;
				let ang1 = (last.ang + TAU) % TAU;
				let dang = ang1 - ang0;
				if (dang < -PI) {
					dang = ang1 + TAU - ang0;
				} else if (dang > PI) {
					dang = ang1 - ang0 - TAU;
				}
				let n = int(abs(dang) / radians(1));
				dang /= n;
				let c = prev.center;
				let v = createVector(d * prev.ring, 0).rotate(ang0);
				for (let i = 0; i < n; i++) {
					v.rotate(dang);
					trails[trails.length - 1].push(c.copy().add(v))
				}
			}
		} else trails.push([last.p]);
	}
}

